import json
import os
import warnings
import argparse
from datetime import datetime
from server.storage.stim import AdaptiveReader, StimReader, AdaptiveWriter, StimWriter
from server.storage.neural import NeuralWriter, NeuralReader
from server.storage.events import EventReader, EventWriter
from common.utils.ingest import wasabi_fmt_date, fetch_rcs_date
from server.storage.accelerometer import AccelWriter, AccelReader
from abc import ABC, abstractmethod
from server.settings import OUTPUT_BASE


class CombinedBase(ABC):
    """Base class for common functions of CombinedReader and CombinedWriter"""

    @classmethod
    @abstractmethod
    def date_fetch(cls, date, patient):
        """Fetch all the data for a given day"""
        return cls()

    @property
    def all_modalities(self):
        for mode in [self.neural, self.accel, self.settings, self.events, self.pose, self.power]:
            yield mode

    def __init__(self, neural=None, accel=None, pose=None, settings=None, events=None):
        self.neural = neural
        self.accel = accel
        self.pose = pose
        self.events = events
        self.settings = settings
        self.power = None


class CombinedReader(CombinedBase):
    """
    Read a long
    """

    @classmethod
    def date_fetch(cls, date, patient):
        path = os.path.join(OUTPUT_BASE, patient, f'{date}.h5')
        neural = NeuralReader(path)
        accel = AccelReader(path)
        settings = SettingsReader.date_fetch(date, patient)
        events = EventReader(path)
        return cls(neural=neural, accel=accel, settings=settings, events=events)


class CombinedWriter(CombinedBase):
    """
    Writer for all modalities at once, enabling easier exchange of information between them
    """

    def __init__(self, output, neural=None, accel=None, pose=None, settings=None, events=None):
        self.output = output
        self.delays = None
        super(CombinedWriter, self).__init__(neural=neural, accel=accel, pose=pose, settings=settings, events=events)

    @classmethod
    def date_fetch(cls, date,  patient, output_dir=None, use_delays=False):
        """
        Fetch all the data for a single patient for a single day

        :param date:
        :param patient:
        :param output_dir:
        :param use_delays:

        :returns: A ready CombinedWriter with all attributes ready for loading
        """

        try:
            wasabi_str = wasabi_fmt_date(date)
        except AttributeError:
            wasabi_str = date

        output = os.path.join(output_dir, patient, f'{wasabi_str}.h5')
        os.makedirs(os.path.dirname(output), exist_ok=True)

        left_right = fetch_rcs_date(patient, wasabi_str)

        # Prepare all the sources to load data
        neurals = [NeuralWriter.from_sources(l, r, output) for l, r in left_right]
        accels = [AccelWriter.from_neural_src(output, l, r, patient_id=patient) for l, r in left_right]
        settings = [SettingsWriter.from_sources(l, r, output) for l, r in left_right]
        events = [EventWriter.from_sources(l, r, output) for l, r in left_right]
        poses = [None]

        # Assemble into a ready list of writers
        indiv_combined = [
            CombinedWriter(output, accel=a, neural=n, settings=s, events=e)
            for a, n, s, e in zip(accels, neurals, settings, events)
        ]

        # Optionally save the delays to the appropriate writer
        delays_json = os.path.join(output_dir, patient, 'delays', f'{wasabi_str}.json')
        if use_delays and os.path.exists(delays_json):
            with open(delays_json) as f:
                delays_today = json.load(f)
                for i, d in enumerate(delays_today):
                    this_delay = delays_today[i]
                    indiv_combined[i] = this_delay

        return indiv_combined

    @classmethod
    def from_stack(cls, writers, patient):
        """Neatly stack each data modality ready for writing to a file"""
        neural = NeuralWriter.from_stack([w.neural for w in writers])
        accel = AccelWriter.from_stack([w.accel for w in writers], patient=patient)
        setting = SettingsWriter.from_stack([w.settings for w in writers])
        event = EventWriter.from_stack([w.events for w in writers])
        pose = None  # TODO: PoseWriter.from_stack(poses)

        stacked = cls(writers[0].output, neural=neural, accel=accel, pose=pose, settings=setting, events=event)
        return stacked

    def load(self):
        if self.delays:
            self.accel.set_alignments(self.delays)
        self.accel.load()

        self.neural.collect_alignments(**self.accel.alignments)
        self.neural.load()
        self.settings.collect_alignments(**self.accel.alignments)
        self.settings.load()
        self.events.collect_alignments(**self.accel.alignments)
        self.events.load()

        # Load and align the pose data to the right wristwatch time
        # TODO: actually make this happen

    def write(self, overwrite=False):
        """Write all components (modalities) into a single hdf5 file"""
        if overwrite and os.path.exists(self.output):
            os.remove(self.output)
        for mode in self.all_modalities:
            try:
                mode.write()
            except AttributeError:
                warnings.warn("this modality is probably not implemented yet")


class SettingsReader(object):

    def __init__(self, stim=None, adaptive=None):

        self.stim = stim
        self.adaptive = adaptive

    @property
    def all_settings(self):
        for s in [self.adaptive, self.stim]:
            if s is not None:
                yield s
            else:
                continue

    @classmethod
    def date_fetch(cls, date, patient):
        path = os.path.join(OUTPUT_BASE, patient, f'{date}.h5')
        stim = StimReader(path)
        adaptive = AdaptiveReader(path)
        return cls(adaptive=adaptive, stim=stim)


class SettingsWriter(SettingsReader):

    @classmethod
    def from_sources(cls, left, right, target):
        try:
            adaptive = AdaptiveWriter.from_sources(left, right, target)
        except FileNotFoundError:
            adaptive = None
        stim = StimWriter.from_sources(left, right, target)
        return cls(stim=stim, adaptive=adaptive)

    @classmethod
    def from_stack(cls, writers):
        stim = StimWriter.from_stack([w.stim for w in writers])
        try:
            adaptive = AdaptiveWriter.from_stack([w.adaptive for w in writers])
        except AttributeError:
            adaptive = None
        return cls(stim=stim, adaptive=adaptive)

    def collect_alignments(self, **alignments):
        if self.adaptive is not None:
            self.adaptive.collect_alignments(**alignments)
        self.stim.collect_alignments(**alignments)

    def load(self):
        for s in self.all_settings:
            s.load()

    def write(self):
        for s in self.all_settings:
            s._soft_write = True
            s.write()


if __name__ == "__main__":

    parser = argparse.ArgumentParser()
    parser.add_argument('--write', action='store_true')
    parser.add_argument('--read', action='store_true')
    parser.set_defaults(feature=False)
    args = parser.parse_args()

    date = datetime(year=2022, month=2, day=27)
    date_str = wasabi_fmt_date(date)

    if args.write:

        patient = 'rcs07'
        try:
            os.remove(os.path.join(OUTPUT_BASE, f'{date_str}.h5'))
        except FileNotFoundError:
            pass
        combined = CombinedWriter.date_fetch(
            date,
            output_dir=OUTPUT_BASE,
            patient='rcs07', use_delays=True
        )
        for c in combined:
            c.load()
        all_combined = CombinedWriter.from_stack(combined, patient)
        all_combined.write()
        pass

    if args.read:
        combined = CombinedReader.date_fetch(date_str, patient='rcs07')
        neural, accel = combined.neural.read(), combined.accel.read()
